export const paginatedTableDisplayMessage = <T extends { count: number }>(
    currentPage: number,
    data: T,
): string => {
    if (!data) return '';
    const currentInitialRangeNumber = currentPage > 1 ? currentPage * 10 + 1 : 1;
    const currentFinalRangeNumber = data.count > currentPage * 10 ? currentPage * 10 : data.count;
    const totalNumberOfRecords = data.count || 0;
    return `Mostrando ${currentInitialRangeNumber} - ${currentFinalRangeNumber} no total de ${totalNumberOfRecords} registros.`;
};

