61	function useNotchClipPath(ref: React.RefObject<HTMLDivElement | null>) {
62	    const [notch, setNotch] = useState<{ d: string; w: number; h: number } | null>(null);
63	
64	    const update = useCallback(() => {
65	        const el = ref.current;
66	        if (!el) return;
67	        const w = el.offsetWidth;
68	        const h = el.offsetHeight;
69	        if (!w || !h) return;
70	
71	        const r = 24;
72	        // Notch adapta à largura do container (notebook/tablet) em vez de 400px fixos
73	        const nw = Math.min(400, Math.max(220, w - 40));
74	        const nh = w < 900 ? 48 : 54;
75	        const nr = 13;
76	        const ir = Math.min(26, Math.floor(nh / 2));
77	        const nx = (w - nw) / 2;
78	
79	        const d = [
80	            `M ${r},0`,
81	            `L ${nx - nr},0`,
82	            `Q ${nx},0 ${nx},${nr}`,
83	            `L ${nx},${nh - ir}`,
84	            `Q ${nx},${nh} ${nx + ir},${nh}`,
85	            `L ${nx + nw - ir},${nh}`,
86	            `Q ${nx + nw},${nh} ${nx + nw},${nh - ir}`,
87	            `L ${nx + nw},${nr}`,
88	            `Q ${nx + nw},0 ${nx + nw + nr},0`,
89	            `L ${w - r},0`,
90	            `Q ${w},0 ${w},${r}`,
91	            `L ${w},${h - r}`,
92	            `Q ${w},${h} ${w - r},${h}`,
93	            `L ${r},${h}`,
94	            `Q 0,${h} 0,${h - r}`,
95	            `L 0,${r}`,
96	            `Q 0,0 ${r},0 Z`,
97	        ].join(' ');
98	
99	        el.style.clipPath = `path("${d}")`;
100	        setNotch((prev) =>
101	            prev && prev.d === d && prev.w === w && prev.h === h ? prev : { d, w, h },
102	        );
103	    }, [ref]);
104	
105	    useEffect(() => {
106	        let ro: ResizeObserver | null = null;
107	        let raf: number;
108	        let poll: ReturnType<typeof setInterval> | null = null;
109	
110	        function setup() {
111	            const el = ref.current;
112	            if (!el) return false;
113	            update();
114	            ro = new ResizeObserver(update);
115	            ro.observe(el);
116	            window.addEventListener('resize', update);
117	            raf = requestAnimationFrame(update);
118	            return true;
119	        }
120	
121	        // Se o elemento ainda não está no DOM (render condicional),
122	        // fica em polling de 50ms até que ele apareça.
123	        if (!setup()) {
124	            poll = setInterval(() => {
125	                if (setup()) {
126	                    clearInterval(poll!);
127	                    poll = null;
128	                }
129	            }, 50);
130	        }
131	
132	        return () => {
133	            if (poll) clearInterval(poll);
134	            ro?.disconnect();
135	            window.removeEventListener('resize', update);
136	            cancelAnimationFrame(raf);
137	        };
138	    }, [update, ref]);
139	
140	    return notch;
141	}
