'use client';

import { EditProjectionScenarioForm } from '@/components/Forms/PostAquisition/EditProjectionScenario';

import { Badge } from '@/components/ui/badge';


import { ScenariosListPaginationSkeleton, ScenariosListSkeleton } from '@/components/Skeletons/ScenariosListSkeleton';
import { Button } from '@/components/ui/button';
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from '@/components/ui/dialog';
import dateFormater from '@/functions/formaters/dateFormater';
import { createScenariosQueryOptions } from '@/hooks/queries/post-purchase';
import { cn } from '@/lib/utils';
import { ProjectionScenario } from '@/types/posAquisicao';
import { paginatedTableDisplayMessage } from '@/utils/paginatedTableDisplayMessage';
import queryClient from '@/utils/queryClient';
import { useQuery } from '@tanstack/react-query';
import { ChevronLeft, ChevronRight, MoveRight, Pencil, Trash2 } from 'lucide-react';
import { AnimatePresence } from 'motion/react';
import { useEffect, useState } from 'react';
import { DeleteScenarioOverlay } from './DeleteOverlay';

interface EditProjectionScenariosModalProps {
    isOpen: boolean;
    onClose: () => void;
}

const BADGE_COLORS = {
    'Conservador': 'bg-green-50 text-green-500 border-green-200',
    'Realista': 'bg-blue-50 text-blue-500 border-blue-200',
    'Otimista': 'bg-orange-50 text-orange-500 border-orange-200',
};

/**
 * Modal para edição e remoção de cenários de projeção.
 * 
 * @param isOpen - Estado de abertura do modal
 * @param onClose - Função para fechar o modal
 */
export function EditProjectionScenariosModal({ isOpen, onClose }: EditProjectionScenariosModalProps) {

    const [currentPage, setCurrentPage] = useState<number>(1);
    const [isEditing, setIsEditing] = useState<boolean>(false);
    const [selectedScenario, setSelectedScenario] = useState<ProjectionScenario | null>(null);
    const [scenarioIdToDelete, setScenarioIdToDelete] = useState<number | null>(null);

    const { data: scenarios, isLoading } = useQuery(createScenariosQueryOptions(currentPage));

    function handleChangePage(direction: 'next' | 'previous') {
        if (direction === 'next') {
            setCurrentPage((prevPage) => prevPage + 1);
        } else {
            setCurrentPage((prevPage) => prevPage - 1);
        }
    }

    function handleEditScenario(scenario: ProjectionScenario) {
        setSelectedScenario(scenario);
        setIsEditing(true);
    }

    function handleCloseEditScenarioForm() {
        setSelectedScenario(null);
        setIsEditing(false);
    }

    useEffect(() => {
        if (scenarios?.next) {
            const nextPage = currentPage + 1;
            queryClient.prefetchQuery(createScenariosQueryOptions(nextPage));
        }
    }, [scenarios, currentPage]);

    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent className="max-w-sm sm:max-w-[600px] p-6">
                <DialogHeader className="mb-4">
                    <DialogTitle className="text-xl font-bold text-subtitle">Editar Cenários</DialogTitle>
                    <DialogDescription className="text-sm text-paragraph">
                        Altere ou remova cenários cadastrados.
                    </DialogDescription>
                </DialogHeader>

                <div className="overflow-hidden">
                    <div className={cn("w-[200%] overflow-hidden flex pr-2 gap-2 transition-transform duration-300 ease-in-out",
                        isEditing ? '-translate-x-1/2' : 'translate-x-0'
                    )}>

                        {/* exibe os itens em linha (modo padrão) */}
                        <div className="flex flex-col w-1/2 max-h-[400px] overflow-y-auto custom-scrollbar">
                            {isLoading ? (
                                <ScenariosListSkeleton />
                            ) : scenarios?.results && scenarios?.results?.length > 0 ? (
                                <>
                                    {scenarios?.results.map((scenario, index) => {
                                        const isLast = index !== scenarios.results.length - 1;
                                        return (
                                            <div
                                                key={`scenario-${scenario.id}`}
                                                className={`group/line relative flex items-center justify-between max-w-full overflow-hidden py-4 ${isLast ? 'border-b border-border' : ''
                                                    }`}
                                            >
                                                <AnimatePresence>
                                                    {scenarioIdToDelete === scenario.id && (
                                                        <DeleteScenarioOverlay
                                                            scenario={scenario}
                                                            setScenarioIdToDelete={setScenarioIdToDelete}
                                                        />
                                                    )}
                                                </AnimatePresence>

                                                <div className="flex gap-5 flex-col sm:flex-row">

                                                    <div className="space-y-1 border-r border-border pr-2 min-w-8">
                                                        <p className="text-xs font-semibold text-paragraph">
                                                            ID
                                                        </p>
                                                        <p className="text-sm text-subtitle">
                                                            {scenario.id}
                                                        </p>
                                                    </div>

                                                    <div className="flex gap-7">
                                                        <div className="space-y-1 min-w-25">
                                                            <p className="text-xs uppercase font-semibold text-paragraph">
                                                                Cenário
                                                            </p>
                                                            <Badge
                                                                className={cn("text-sx rounded-lg", BADGE_COLORS[scenario.scenario])}
                                                            >
                                                                {scenario.scenario}
                                                            </Badge>
                                                        </div>
                                                        <div className="space-y-1">
                                                            <p className="text-xs uppercase font-semibold text-paragraph">
                                                                Período
                                                            </p>
                                                            <div className="flex items-center gap-3">
                                                                <Badge
                                                                    className={cn("text-sx rounded-lg bg-gray-50 text-gray-500 border-gray-200")}
                                                                >
                                                                    {dateFormater(scenario.start_date)}
                                                                </Badge>

                                                                <MoveRight size={16} />

                                                                <Badge
                                                                    className={cn("text-sx rounded-lg bg-gray-50 text-gray-500 border-gray-200")}
                                                                >
                                                                    {dateFormater(scenario.end_date)}
                                                                </Badge>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                                <div className="group-hover/line:opacity-100 opacity-0 group-hover/line:translate-x-0 translate-x-1/2 transition-all duration-200 flex items-center gap-2">
                                                    <Button
                                                        size="icon"
                                                        title="Editar cenário"
                                                        className="size-7 shadow-none bg-transparent text-subtitle hover:bg-blue-50 hover:text-blue-500 rounded-md"
                                                        onClick={() => handleEditScenario(scenario)}
                                                    >
                                                        <Pencil size={14} />
                                                    </Button>

                                                    <Button
                                                        size="icon"
                                                        title="Remover cenário"
                                                        className="size-7 shadow-none bg-transparent text-subtitle hover:bg-red-50 hover:text-red-500 rounded-md"
                                                        onClick={() => setScenarioIdToDelete(scenario.id)}
                                                    >
                                                        <Trash2 size={14} />
                                                    </Button>
                                                </div>
                                            </div>
                                        );
                                    })}
                                </>
                            ) : (
                                <div className="flex flex-col items-center justify-center h-25">
                                    <p className="text-sm text-paragraph">Nenhum cenário encontrado</p>
                                </div>
                            )}
                        </div>

                        <div className="flex flex-col w-1/2">
                            {selectedScenario && isEditing && (
                                <EditProjectionScenarioForm
                                    scenario={selectedScenario}
                                    onClose={handleCloseEditScenarioForm}
                                />
                            )}
                        </div>
                    </div>
                </div>
                {(scenarios || isLoading) && !isEditing && (
                    <>
                        {isLoading ? (
                            <ScenariosListPaginationSkeleton />
                        ) : (
                            <div className="flex items-center justify-between mt-4 pt-4 border-t border-gray-100">
                                <div className="flex-1 text-sm text-paragraph">
                                    {scenarios && paginatedTableDisplayMessage(currentPage, scenarios)}
                                </div>

                                <div className="flex items-center gap-4">
                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        className="h-8 w-8 text-gray-400 hover:text-gray-600"
                                        disabled={currentPage === 1}
                                        onClick={() => handleChangePage('previous')}
                                    >
                                        <ChevronLeft size={18} />
                                    </Button>
                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        className="h-8 w-8 text-gray-400 hover:text-gray-600"
                                        disabled={!scenarios?.next}
                                        onClick={() => handleChangePage('next')}
                                    >
                                        <ChevronRight size={18} />
                                    </Button>
                                </div>
                            </div>
                        )}
                    </>
                )}


            </DialogContent>
        </Dialog>
    );
}

