'use client';
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table';
import { COLORS, withAlpha } from '@/design-system';
import { isUserMasterOrDev } from '@/functions/rulesVerification';
import { useBrokerStore } from '@/store/useBroker';
import { useUserInfoStore } from '@/store/userInfo';
import { BrokerUltralightResults } from '@/types/broker';
import { paginatedTableDisplayMessage } from '@/utils/paginatedTableDisplayMessage';
import {
    flexRender,
    getCoreRowModel,
    getFilteredRowModel,
    getPaginationRowModel,
    getSortedRowModel,
    useReactTable
} from '@tanstack/react-table';
import { ChevronDown, ChevronLeft, ChevronRight, ChevronUp, LoaderCircle } from 'lucide-react';
import { useShallow } from 'zustand/react/shallow';
import { useProposalList } from '../../broker/_components/BrokerInfo/ProposalListWrapper';
import { GerencialToolbarButton } from '../_components/shared/GerencialTableAction';
import { GERENCIAL_TABLE_HEAD_ROW_CLASS, GERENCIAL_TABLE_HEAD_TEXT_CLASS } from '../_constants/gerencial-ui';
import { createColumns } from './columns';

export function BrokerPrecatoriosTable() {
    /**
     * ===========>> STORE CONSTS <<==============
     */
    const isCoordenadorOrMaster = useBrokerStore((store) => store.isCoordenadorOrMaster);
    const { userRole } = useUserInfoStore(
        useShallow((s) => ({ userRole: s.data.role, userName: s.data.user, userId: s.data.id })),
    );

    // ===============
    // # Context
    // ===============
    const { proposalListData, isLoading, isError, handleChangePage, currentPage } = useProposalList();

    /**
     * ===========>> TABLE STATES <<==============
     */
    // const [currentPage, setCurrentPage] = useState(1);

    /**
     * ==========>> CONSTS <<==============
     */
    const columns = createColumns(currentPage);
    const filteredColumns = columns.filter((col) => {
        if (col.id === 'usuario' && !isCoordenadorOrMaster && !isUserMasterOrDev(userRole)) {
            return false;
        }

        return true;
    });

    const table = useReactTable({
        data: proposalListData?.results as BrokerUltralightResults[],
        columns: filteredColumns,
        getCoreRowModel: getCoreRowModel(),
        getPaginationRowModel: getPaginationRowModel(),
        getSortedRowModel: getSortedRowModel(),
        getFilteredRowModel: getFilteredRowModel()
    });

    return (
        <>

            <div className="overflow-auto rounded-md border">
                <Table className={GERENCIAL_TABLE_HEAD_ROW_CLASS}>
                    <caption className="sr-only">
                        Lista de propostas de precatórios do broker, com ordenação por coluna e paginação.
                    </caption>
                    <TableHeader className="bg-muted/30">
                        {table.getHeaderGroups().map((headerGroup) => (
                            <TableRow
                                key={headerGroup.id}
                                className="hover:bg-muted/30"
                            >
                                {headerGroup.headers.map((header) => (
                                    <TableHead key={header.id}>
                                        {header.isPlaceholder ? null : (
                                            <div
                                                className={
                                                    header.column.getCanSort()
                                                        ? `flex cursor-pointer select-none items-center gap-1 ${GERENCIAL_TABLE_HEAD_TEXT_CLASS}`
                                                        : GERENCIAL_TABLE_HEAD_TEXT_CLASS
                                                }
                                                {...(header.column.getCanSort()
                                                    ? {
                                                          onClick: header.column.getToggleSortingHandler(),
                                                          role: 'button' as const,
                                                          tabIndex: 0,
                                                          'aria-label': `Ordenar por ${header.column.columnDef.header}`,
                                                          onKeyDown: (e) => {
                                                              if (e.key === 'Enter' || e.key === ' ') {
                                                                  e.preventDefault();
                                                                  header.column.toggleSorting();
                                                              }
                                                          },
                                                      }
                                                    : {})}
                                            >
                                                {flexRender(
                                                    header.column.columnDef.header,
                                                    header.getContext(),
                                                )}
                                                {{
                                                    asc: (
                                                        <ChevronUp
                                                            className="h-4 w-4"
                                                            aria-hidden="true"
                                                        />
                                                    ),
                                                    desc: (
                                                        <ChevronDown
                                                            className="h-4 w-4"
                                                            aria-hidden="true"
                                                        />
                                                    ),
                                                }[header.column.getIsSorted() as string] ?? null}
                                            </div>
                                        )}
                                    </TableHead>
                                ))}
                            </TableRow>
                        ))}
                    </TableHeader>
                    <TableBody>
                        {proposalListData && table.getRowModel().rows?.length ? (
                            table.getRowModel().rows.map((row) => (
                                <TableRow
                                    className="group"
                                    style={
                                        row.original.status === 'Transação Concluída'
                                            ? { background: withAlpha(COLORS.green, 0.08) }
                                            : undefined
                                    }
                                    key={row.id}
                                    data-state={row.getIsSelected() && 'selected'}
                                >
                                    {row.getVisibleCells().map((cell) => (
                                        <TableCell key={cell.id}>
                                            {flexRender(
                                                cell.column.columnDef.cell,
                                                cell.getContext(),
                                            )}
                                        </TableCell>
                                    ))}
                                </TableRow>
                            ))
                        ) : (
                            <TableRow>
                                <TableCell colSpan={8} className="h-24 text-center">
                                    {isLoading && (
                                        <div className="flex animate-fade items-center justify-center gap-2 text-sm text-muted-foreground">
                                            <LoaderCircle
                                                className="h-5 w-5 animate-spin"
                                                style={{ color: COLORS.brand }}
                                                aria-hidden
                                            />
                                            <span>Carregando...</span>
                                        </div>
                                    )}
                                    {!isLoading && (
                                        <span className="animate-fade">
                                            Nenhum registro encontrado
                                        </span>
                                    )}
                                    {isError && (
                                        <span className="animate-fade">
                                            Erro ao carregar os dados. Tente novamente.
                                        </span>
                                    )}
                                </TableCell>
                            </TableRow>
                        )}
                    </TableBody>
                </Table>
            </div>

            {proposalListData && (
                <div className="flex flex-col items-center justify-between space-x-0 space-y-3 py-4 sm:flex-row sm:space-x-2 sm:space-y-0">
                    <div className="flex-1 text-sm text-muted-foreground">
                        {paginatedTableDisplayMessage(currentPage, proposalListData)}
                    </div>
                    <div className="flex items-center space-x-2">
                        <GerencialToolbarButton
                            className="gap-1.5"
                            onClick={() => handleChangePage('previous')}
                            disabled={!proposalListData?.previous}
                            aria-label="Página anterior"
                        >
                            <ChevronLeft className="h-3.5 w-3.5" aria-hidden />
                            Anterior
                        </GerencialToolbarButton>
                        <GerencialToolbarButton
                            className="gap-1.5"
                            onClick={() => handleChangePage('next')}
                            disabled={!proposalListData?.next}
                            aria-label="Próxima página"
                        >
                            Próximo
                            <ChevronRight className="h-3.5 w-3.5" aria-hidden />
                        </GerencialToolbarButton>
                    </div>
                </div>
            )}
        </>
    );
}

'use client';

import { ErrorMessageBox } from '@/components/ErrorMessage/ErrorMessageBox';
import { Button } from '@/components/ui/button';
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table';
import { TooltipProvider } from '@/components/ui/tooltip';
import { APP_ROUTES } from '@/constants/app-routes';
import { cn } from '@/lib/utils';
import { BrokerUltralightResults } from '@/types/broker';
import { paginatedTableDisplayMessage } from '@/utils/paginatedTableDisplayMessage';
import {
    flexRender,
    getCoreRowModel,
    getFilteredRowModel,
    getPaginationRowModel,
    getSortedRowModel,
    useReactTable,
} from '@tanstack/react-table';
import { MousePointerClick } from 'lucide-react';
import Link from 'next/link';
import { useProposalList } from '../ProposalListWrapper';
import { BrokerInfoTableSkeleton } from '../Skeletons';
import { brokerInfoTableColumnsUltralight } from './TableColumnsUltralight';

export function BrokerInfoTable() {
    const {
        proposalListData,
        isLoading,
        isError,
        isRefetching,
        refetch,
        currentPage,
        handleChangePage,
    } = useProposalList();
    const table = useReactTable({
        data: (proposalListData?.results as BrokerUltralightResults[]) || [],
        columns: brokerInfoTableColumnsUltralight,
        getCoreRowModel: getCoreRowModel(),
        getPaginationRowModel: getPaginationRowModel(),
        getSortedRowModel: getSortedRowModel(),
        getFilteredRowModel: getFilteredRowModel(),
        initialState: {
            pagination: {
                pageSize: 10,
            },
        },
    });

    if (isLoading) return <BrokerInfoTableSkeleton />;

    return (
        <div className="w-full">
            <TooltipProvider delayDuration={100}>
                <Table className="min-w-[980px] pb-5">
                    <TableHeader>
                        {table.getHeaderGroups().map((headerGroup) => (
                            <TableRow
                                key={headerGroup.id}
                                className="bg-slate-50 text-left text-xs font-semibold uppercase hover:bg-slate-50 dark:bg-boxdark-2 dark:hover:bg-boxdark-2"
                            >
                                {headerGroup.headers.map((header) => (
                                    <TableHead
                                        key={header.id}
                                        className="first:rounded-tl-xl last:rounded-tr-xl"
                                    >
                                        {flexRender(
                                            header.column.columnDef.header,
                                            header.getContext(),
                                        )}
                                    </TableHead>
                                ))}
                            </TableRow>
                        ))}
                    </TableHeader>
                    <TableBody>
                        {proposalListData && table?.getRowModel()?.rows?.length ? (
                            table.getRowModel().rows.map((row) => {
                                const hasPendencies = row.original.status === 'Pendência a Sanar';
                                return (
                                    <TableRow
                                        className={cn(
                                            'group/broker-table-row relative cursor-pointer transition-colors hover:bg-slate-50 dark:hover:bg-slate-800/50',
                                            hasPendencies &&
                                            'bg-red-50/50 hover:bg-red-50 dark:bg-red-950/10 dark:hover:bg-red-950/20',
                                        )}
                                        key={row.id}
                                    >
                                        {row.getVisibleCells().map((cell) => (
                                            <TableCell key={cell.id} className="relative">
                                                {flexRender(
                                                    cell.column.columnDef.cell,
                                                    cell.getContext(),
                                                )}
                                            </TableCell>
                                        ))}
                                        <TableCell className="pointer-events-none absolute inset-0 p-0">
                                            <Link
                                                href={APP_ROUTES.private.brokerOficioDetails.name(
                                                    row.original.extrato_id,
                                                )}
                                                className="pointer-events-auto absolute inset-0 flex items-center justify-center gap-2 bg-zinc-100/10 text-white opacity-0 backdrop-blur-[2px] transition-opacity duration-300 group-hover/broker-table-row:opacity-100 dark:bg-slate-900/10"
                                            >
                                                <MousePointerClick
                                                    size={16}
                                                    className="text-black-2 dark:text-snow"
                                                />
                                                <span className="text-sm font-medium text-black-2 dark:text-snow">
                                                    Clique aqui para continuar a negociação do
                                                    precatório
                                                </span>
                                            </Link>
                                        </TableCell>
                                    </TableRow>
                                );
                            })
                        ) : (
                            <TableRow>
                                <TableCell colSpan={8} className="h-24 text-center">
                                    {proposalListData?.results.length === 0 && (
                                        <span className="animate-fade">
                                            Nenhum registro encontrado
                                        </span>
                                    )}
                                    {isError && (
                                        <ErrorMessageBox
                                            className="border-0 shadow-none"
                                            retryFn={refetch}
                                            isRetrying={isRefetching}
                                        />
                                    )}
                                </TableCell>
                            </TableRow>
                        )}
                    </TableBody>
                </Table>
            </TooltipProvider>

            {proposalListData && (
                <div className="flex flex-col items-center justify-between space-x-0 space-y-3 py-4 sm:flex-row sm:space-x-2 sm:space-y-0">
                    <div className="flex-1 text-sm text-muted-foreground">
                        {paginatedTableDisplayMessage(currentPage, proposalListData)}
                    </div>
                    <div className="flex items-center space-x-2">
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleChangePage('previous')}
                            disabled={!proposalListData?.previous}
                            aria-label="Página anterior"
                        >
                            ← Anterior
                        </Button>
                        <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleChangePage('next')}
                            disabled={!proposalListData?.next}
                            aria-label="Próxima página"
                        >
                            Próximo →
                        </Button>
                    </div>
                </div>
            )}
        </div>
    );
}

