389	                networkPage,
390	                activeTab,
391	                tableData,
392	                networkTableData,
393	                showSkeleton,
394	                showNetworkSkeleton,
395	            ],
396	            revertOnUpdate: true,
397	        },
398	    );
399	
400	    const activeData = activeTab === 'meus' ? data : networkData;
401	    const activePage = activeTab === 'meus' ? currentPage : networkPage;
402	    const activeIsFetching = activeTab === 'meus' ? isFetching : networkFetching;
