'use client';

import { useBrokerUltralightTableFilters } from '@/app/crm/broker/_hooks/useBrokerUltralightTableFilters';
import { animatePdfIntoNovoPrecatorio } from '@/app/crm/broker/_components/activation';
import { PrecatoriosTableBodySkeleton } from './PrecatoriosTableBodySkeleton';
import { PrecatoriosTableFiltersBar } from './PrecatoriosTableFiltersBar';
import {
    PrecatoriosMeusMobileList,
    PrecatoriosRedeMobileList,
} from './PrecatoriosTableMobileList';
import { TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { TooltipProvider } from '@/components/ui/tooltip';
import { APP_ROUTES } from '@/constants/app-routes';
import { getPropostaStatusBadgeColor } from '@/constants/status';
import { countElapsedCalendarDays } from '@/functions/broker/count-elapsed-calendar-days';
import numberFormat from '@/functions/formaters/numberFormat';
import {
    createBrokerDashboardTableUltralightQueryOptions,
    createBrokerNetworkProposalsQueryOptions,
} from '@/hooks/queries/broker';
import { useIsMobileOrTablet } from '@/hooks/use-mobile-or-tablet';
import { cn } from '@/lib/utils';
import { BrokerUltralightResults, NetworkProposalData } from '@/types/broker';
import { useUserInfoStore } from '@/store/userInfo';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { flexRender, getCoreRowModel, useReactTable, ColumnDef } from '@tanstack/react-table';
import gsap from 'gsap';
import { useGSAP } from '@gsap/react';
import { ChevronLeft, ChevronRight, Lock, MousePointerClick } from 'lucide-react';
import Link from 'next/link';
import { useEffect, useMemo, useRef, useState } from 'react';
import { useShallow } from 'zustand/react/shallow';
import { paginatedTableDisplayMessage } from '@/utils/paginatedTableDisplayMessage';
import { useBentoTheme } from '../../../_hooks/useBentoTheme';

gsap.registerPlugin(useGSAP);

function formatMoney(value: string | undefined | null) {
    if (!value) return '-';
    const numeric = Number(value);
    if (Number.isNaN(numeric)) return '-';
    return numberFormat(numeric);
}

type StatusTone = 'success' | 'warning' | 'danger' | 'neutral';

function getStatusIndicator(isComplete: boolean | undefined | null) {
    if (isComplete === true) return { tone: 'success' as StatusTone, label: 'Concluído' };
    if (isComplete === false) return { tone: 'danger' as StatusTone, label: 'Pendente' };
    return { tone: 'warning' as StatusTone, label: 'Em análise' };
}

// ── Modern local badge components ─────────────────────────────────────────────

const BADGE_STYLES: Record<string, { pill: string; dot: string }> = {
    green:  { pill: 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-400', dot: 'bg-emerald-500 [box-shadow:0_0_5px_rgba(16,185,129,0.7)]'  },
    red:    { pill: 'bg-rose-500/10 text-rose-700 dark:text-rose-400',          dot: 'bg-rose-500 [box-shadow:0_0_5px_rgba(244,63,94,0.7)]'      },
    yellow: { pill: 'bg-amber-500/10 text-amber-700 dark:text-amber-400',       dot: 'bg-amber-400 [box-shadow:0_0_5px_rgba(251,191,36,0.6)]'    },
    blue:   { pill: 'bg-blue-500/10 text-blue-700 dark:text-blue-400',          dot: 'bg-blue-500 [box-shadow:0_0_5px_rgba(59,130,246,0.7)]'     },
    purple: { pill: 'bg-violet-500/10 text-violet-700 dark:text-violet-400',    dot: 'bg-violet-500 [box-shadow:0_0_5px_rgba(139,92,246,0.7)]'   },
    orange: { pill: 'bg-orange-500/10 text-orange-700 dark:text-orange-400',    dot: 'bg-orange-500 [box-shadow:0_0_5px_rgba(249,115,22,0.7)]'   },
    grey:   { pill: 'bg-slate-500/10 text-slate-500 dark:text-slate-400',       dot: 'bg-slate-400'                                              },
};

function BentoDaysInSystemBadge({ dateStr }: { dateStr: string | undefined | null }) {
    const days = countElapsedCalendarDays(dateStr);
    if (days === null) return <span className="text-slate-400 dark:text-slate-500">-</span>;
    const color = days < 20 ? 'green' : days < 60 ? 'yellow' : 'red';
    const { pill } = BADGE_STYLES[color];
    return (
        <span className={cn('inline-flex items-center whitespace-nowrap rounded-full px-2 py-0.5 text-[10px] 4xl:text-[15px] font-medium tabular-nums', pill)}>
            {days} dias
        </span>
    );
}

function BentoStatusBadge({ status }: { status: string | undefined | null }) {
    const color = getPropostaStatusBadgeColor(status);
    const { pill, dot } = BADGE_STYLES[color] ?? BADGE_STYLES.grey;
    return (
        <span className={cn('inline-flex items-center gap-1.5 rounded-full px-2 py-0.5 text-[10px] 4xl:text-[15px] font-medium', pill)}>
            <span className={cn('size-1.5 shrink-0 rounded-full', dot)} />
            <span className="bento-status-badge-label max-w-[100px] truncate">{status ?? 'Sem status'}</span>
        </span>
    );
}

const PIP_STYLES: Record<StatusTone, string> = {
    success: 'bg-emerald-500 [box-shadow:0_0_6px_rgba(16,185,129,0.7)]',
    warning: 'bg-amber-400 [box-shadow:0_0_6px_rgba(251,191,36,0.55)]',
    danger:  'bg-rose-500 [box-shadow:0_0_6px_rgba(244,63,94,0.7)]',
    neutral: 'bg-slate-400',
};

function BentoCompletionPip({ isComplete }: { isComplete: boolean | undefined | null }) {
    const { tone, label } = getStatusIndicator(isComplete);
    return (
        <span title={label} className={cn('inline-block size-3 rounded-full', PIP_STYLES[tone])} />
    );
}

// --- Meus Precatórios columns ---
const collapsedColumns: ColumnDef<BrokerUltralightResults>[] = [
    {
        id: 'creditor',
        header: 'Nome do Credor',
        cell: ({ row }) => (
            <p className="max-w-full truncate font-medium text-slate-800 dark:text-slate-200">{row.original.credor}</p>
        ),
    },
    {
        id: 'netValue',
        header: 'Valor Líquido',
        cell: ({ row }) => (
            <span className="whitespace-nowrap tabular-nums text-slate-600 dark:text-slate-300">
                {formatMoney(row.original.valor_liquido)}
            </span>
        ),
    },
    {
        id: 'daysInSystem',
        header: () => (
            <>
                <span className="precatorios-table-days-label-long">Dias em sistema</span>
                <span className="precatorios-table-days-label-short">Dias</span>
            </>
        ),
        cell: ({ row }) => <BentoDaysInSystemBadge dateStr={row.original.created_at} />,
    },
    {
        id: 'status',
        header: 'Status',
        cell: ({ row }) => <BentoStatusBadge status={row.original.status_proposta} />,
    },
];

const expandedColumns: ColumnDef<BrokerUltralightResults>[] = [
    ...collapsedColumns.slice(0, 2),
    {
        id: 'proposal',
        header: 'Proposta',
        cell: ({ row }) => (
            <span className="whitespace-nowrap tabular-nums text-slate-600 dark:text-slate-300">
                {formatMoney(row.original.proposta)}
            </span>
        ),
    },
    {
        id: 'commission',
        header: 'Comissão',
        cell: ({ row }) => (
            <span className="whitespace-nowrap tabular-nums text-slate-600 dark:text-slate-300">
                {formatMoney(row.original.comissao)}
            </span>
        ),
    },
    {
        id: 'precatorio',
        header: 'Precatório',
        cell: ({ row }) => <BentoCompletionPip isComplete={row.original.requisitos_oficio?.is_complete} />,
    },
    {
        id: 'registration',
        header: 'Cadastro',
        cell: ({ row }) => <BentoCompletionPip isComplete={row.original.cadastro?.is_complete} />,
    },
    {
        id: 'documents',
        header: 'Documentos',
        cell: ({ row }) => <BentoCompletionPip isComplete={row.original.documentos?.is_complete} />,
    },
    collapsedColumns[2], // daysInSystem
    collapsedColumns[3], // status
];

// --- Rede de Brokers columns ---
const networkCollapsedColumns: ColumnDef<NetworkProposalData>[] = [
    {
        id: 'credor',
        header: 'Credor',
        cell: ({ row }) => (
            <div className="flex max-w-full items-center gap-1.5 truncate">
                <Lock className="h-3 w-3 shrink-0 text-slate-400 dark:text-slate-500" />
                <span className="truncate italic text-slate-500 dark:text-slate-400">{row.original.credor}</span>
            </div>
        ),
    },
    {
        id: 'broker',
        header: 'Broker',
        cell: ({ row }) => (
            <span className="font-medium text-slate-700 dark:text-slate-300">
                {row.original.broker?.username ?? '-'}
            </span>
        ),
    },
    {
        id: 'comissao',
        header: 'Comissão',
        cell: ({ row }) => (
            <span className="whitespace-nowrap font-medium tabular-nums text-emerald-600 dark:text-emerald-400">
                {formatMoney(row.original.comissao_rede)}
            </span>
        ),
    },
];

const networkExpandedColumns: ColumnDef<NetworkProposalData>[] = [
    networkCollapsedColumns[0],
    networkCollapsedColumns[1],
    {
        id: 'netValue',
        header: 'Valor Líquido',
        cell: ({ row }) => (
            <span className="whitespace-nowrap tabular-nums text-slate-600 dark:text-slate-300">
                {formatMoney(row.original.valor_liquido)}
            </span>
        ),
    },
    networkCollapsedColumns[2],
    {
        id: 'precatorio',
        header: 'Precatório',
        cell: ({ row }) => <BentoCompletionPip isComplete={row.original.requisitos_oficio?.is_complete} />,
    },
    {
        id: 'registration',
        header: 'Cadastro',
        cell: ({ row }) => <BentoCompletionPip isComplete={row.original.cadastro?.is_complete} />,
    },
    {
        id: 'documents',
        header: 'Documentos',
        cell: ({ row }) => <BentoCompletionPip isComplete={row.original.documentos?.is_complete} />,
    },
    {
        id: 'status',
        header: 'Status',
        cell: ({ row }) => <BentoStatusBadge status={row.original.status_label} />,
    },
];

export type TableTabId = 'meus' | 'rede';

interface PrecatoriosTableBentoCardProps {
    isExpanded: boolean;
    activeTab: TableTabId;
}

export function PrecatoriosTableBentoCard({ isExpanded, activeTab }: PrecatoriosTableBentoCardProps) {
    const scrollRef = useRef<HTMLDivElement>(null);
    const { theme } = useBentoTheme();
    const isMobileOrTablet = useIsMobileOrTablet();
    const queryClient = useQueryClient();
    const [currentPage, setCurrentPage] = useState(1);
    const [networkPage, setNetworkPage] = useState(1);

    const { userName, userId, userHost } = useUserInfoStore(
        useShallow((s) => ({
            userName: s.data.user,
            userId: s.data.id,
            userHost: s.data.host,
        })),
    );

    const {
        filter,
        activeFilters,
        hostToUse,
        searchInputRef,
        debouncedSetCredor,
        setFilters,
        handleRemoveFilter,
        clearAllFilters,
    } = useBrokerUltralightTableFilters({
        userName,
        userHost,
    });

    const [prevFilter, setPrevFilter] = useState(filter);

    if (filter !== prevFilter) {
        setPrevFilter(filter);
        setCurrentPage(1);
    }

    const { data, isLoading, isFetching } = useQuery(
        createBrokerDashboardTableUltralightQueryOptions(
            filter,
            userId,
            userName,
            currentPage,
            hostToUse,
        ),
    );

    const {
        data: networkData,
        isLoading: networkLoading,
        isFetching: networkFetching,
    } = useQuery(
        createBrokerNetworkProposalsQueryOptions(networkPage, [], userHost),
    );

    useEffect(() => {
        setCurrentPage(1);
        setNetworkPage(1);
    }, [userName, userHost]);

    useEffect(() => {
        scrollRef.current?.scrollTo({ top: 0 });
    }, [currentPage, networkPage]);

    useEffect(() => {
        if (!data?.next || !userName || !userId) return;

        const nextPage = currentPage + 1;
        void queryClient.prefetchQuery(
            createBrokerDashboardTableUltralightQueryOptions(
                filter,
                userId,
                userName,
                nextPage,
                hostToUse,
            ),
        );
    }, [currentPage, data?.next, filter, hostToUse, queryClient, userId, userName]);

    useEffect(() => {
        scrollRef.current?.scrollTo({ top: 0 });
    }, [activeTab]);

    function handleChangePage(direction: 'next' | 'previous') {
        setCurrentPage((page) => (direction === 'next' ? page + 1 : page - 1));
    }

    function handleChangeNetworkPage(direction: 'next' | 'previous') {
        setNetworkPage((page) => (direction === 'next' ? page + 1 : page - 1));
    }

    const meusColumns = isExpanded ? expandedColumns : collapsedColumns;
    const redeColumns = isExpanded ? networkExpandedColumns : networkCollapsedColumns;

    const tableData = useMemo(() => data?.results ?? [], [data?.results]);
    const networkTableData = useMemo(() => networkData?.results ?? [], [networkData?.results]);

    const showSkeleton = isLoading || isFetching;
    const showNetworkSkeleton = networkLoading || networkFetching;
    const skeletonRowCount = 10;

    const meusTable = useReactTable({
        data: tableData,
        columns: meusColumns,
        getCoreRowModel: getCoreRowModel(),
    });

    const redeTable = useReactTable({
        data: networkTableData,
        columns: redeColumns,
        getCoreRowModel: getCoreRowModel(),
    });

    useGSAP(
        () => {
            const isSkeleton = activeTab === 'meus' ? showSkeleton : showNetworkSkeleton;
            const activeRows = activeTab === 'meus' ? tableData : networkTableData;
            if (isSkeleton || activeRows.length === 0) return;

            const rows = gsap.utils.toArray<HTMLElement>('.precatorios-table-row');
            if (rows.length === 0) return;

            gsap.fromTo(
                rows,
                { y: 10, opacity: 0 },
                {
                    y: 0,
                    opacity: 1,
                    stagger: 0.05,
                    duration: 0.4,
                    ease: 'power2.out',
                    clearProps: 'opacity,transform',
                },
            );
        },
        {
            scope: scrollRef,
            dependencies: [
                currentPage,
                networkPage,
                activeTab,
                tableData,
                networkTableData,
                showSkeleton,
                showNetworkSkeleton,
            ],
            revertOnUpdate: true,
        },
    );

    const activeData = activeTab === 'meus' ? data : networkData;
    const activePage = activeTab === 'meus' ? currentPage : networkPage;
    const activeIsFetching = activeTab === 'meus' ? isFetching : networkFetching;

    return (
        <TooltipProvider delayDuration={100}>
            <div className="flex h-full min-h-0 flex-col">
                {isExpanded && activeTab === 'meus' && (
                    <PrecatoriosTableFiltersBar
                        searchInputRef={searchInputRef}
                        onSearchChange={debouncedSetCredor}
                        filters={filter}
                        activeFilters={activeFilters}
                        userHost={userHost}
                        setFilters={setFilters}
                        onRemoveFilter={handleRemoveFilter}
                        onClearFilters={clearAllFilters}
                    />
                )}

                <div ref={scrollRef} className="min-h-0 flex-1 overflow-auto pb-1">
                    {isMobileOrTablet ? (
                        activeTab === 'meus' ? (
                            <PrecatoriosMeusMobileList
                                rows={tableData}
                                isExpanded={isExpanded}
                                isLoading={showSkeleton}
                                formatMoney={formatMoney}
                                statusBadge={(status) => <BentoStatusBadge status={status} />}
                                daysBadge={(dateStr) => <BentoDaysInSystemBadge dateStr={dateStr} />}
                                completionPip={(isComplete) => (
                                    <BentoCompletionPip isComplete={isComplete} />
                                )}
                                emptyAction={
                                    <button
                                        type="button"
                                        className="mt-3 text-sm font-semibold text-blue-600 hover:underline dark:text-blue-400"
                                        onClick={(event) => {
                                            animatePdfIntoNovoPrecatorio(event.currentTarget);
                                        }}
                                    >
                                        Ir para Novo Precatório
                                    </button>
                                }
                            />
                        ) : (
                            <PrecatoriosRedeMobileList
                                rows={networkTableData}
                                isExpanded={isExpanded}
                                isLoading={showNetworkSkeleton}
                                formatMoney={formatMoney}
                                statusBadge={(status) => <BentoStatusBadge status={status} />}
                                completionPip={(isComplete) => (
                                    <BentoCompletionPip isComplete={isComplete} />
                                )}
                            />
                        )
                    ) : activeTab === 'meus' ? (
                        <table
                            className={cn(
                                'w-full caption-bottom text-sm 4xl:text-lg',
                                isExpanded ? 'min-w-[720px]' : 'min-w-0',
                            )}
                        >
                            <TableHeader>
                                {meusTable.getHeaderGroups().map((headerGroup) => (
                                    <TableRow
                                        key={headerGroup.id}
                                        className="border-transparent hover:bg-transparent"
                                        style={{ borderColor: theme.divider }}
                                    >
                                        {headerGroup.headers.map((header) => (
                                            <TableHead
                                                key={header.id}
                                                className={cn(
                                                    'precatorios-table-head sticky top-0 z-10 text-[10px] 4xl:text-[15px] uppercase tracking-wider shadow-[0_1px_0_0_var(--bento-divider)] max-[1280px]:text-[9px]',
                                                    isExpanded ? 'h-9 px-3' : 'h-7 px-2',
                                                )}
                                                style={{
                                                    background: theme.tableHeaderBg,
                                                    color: theme.textMuted,
                                                }}
                                            >
                                                {flexRender(
                                                    header.column.columnDef.header,
                                                    header.getContext(),
                                                )}
                                            </TableHead>
                                        ))}
                                    </TableRow>
                                ))}
                            </TableHeader>
                            <TableBody>
                                {showSkeleton ? (
                                    <PrecatoriosTableBodySkeleton
                                        isExpanded={isExpanded}
                                        rowCount={skeletonRowCount}
                                    />
                                ) : meusTable.getRowModel().rows.length === 0 ? (
                                    <TableRow>
                                        <TableCell
                                            colSpan={meusColumns.length}
                                            className="py-8 text-center text-xs 4xl:text-base"
                                            style={{ color: theme.textMuted }}
                                        >
                                            <p className="font-medium" style={{ color: theme.text }}>
                                                Ainda não há precatórios aqui
                                            </p>
                                            <p className="mt-1 max-w-sm mx-auto leading-relaxed">
                                                Solte o ofício no card{' '}
                                                <strong className="font-semibold">Novo Precatório</strong>{' '}
                                                (ou cadastre manualmente). Em seguida você vê o líquido e a
                                                comissão.
                                            </p>
                                            <button
                                                type="button"
                                                className="mt-3 text-sm font-semibold text-blue-600 hover:underline dark:text-blue-400"
                                                onClick={(event) => {
                                                    animatePdfIntoNovoPrecatorio(event.currentTarget);
                                                }}
                                            >
                                                Ir para Novo Precatório
                                            </button>
                                        </TableCell>
                                    </TableRow>
                                ) : (
                                    meusTable.getRowModel().rows.map((row) => (
                                        <TableRow
                                            key={row.id}
                                            className="precatorios-table-row group/precatorios-row relative cursor-pointer border-transparent hover:bg-black/3 dark:hover:bg-white/3"
                                            style={{ borderColor: theme.divider }}
                                        >
                                            {row.getVisibleCells().map((cell) => (
                                                <TableCell
                                                    key={cell.id}
                                                    className={cn(
                                                        'precatorios-table-cell relative text-xs 4xl:text-base max-[1280px]:text-[11px]',
                                                        isExpanded ? 'py-2.5' : 'py-1.5',
                                                    )}
                                                >
                                                    {flexRender(
                                                        cell.column.columnDef.cell,
                                                        cell.getContext(),
                                                    )}
                                                </TableCell>
                                            ))}
                                            <TableCell className="pointer-events-none absolute inset-0 p-0">
                                                <Link
                                                    href={APP_ROUTES.private.brokerOficioDetails.name(
                                                        row.original.extrato_id,
                                                    )}
                                                    className="pointer-events-auto absolute inset-0 flex items-center justify-center gap-2 bg-black/4 text-slate-800 opacity-0 backdrop-blur-[2px] transition-opacity duration-300 group-hover/precatorios-row:opacity-100 dark:bg-white/4 dark:text-slate-200"
                                                    aria-label={`Acessar detalhes da proposta de ${row.original.credor}`}
                                                >
                                                    <MousePointerClick size={16} className="max-[1280px]:size-3.5" />
                                                    <span className="precatorios-table-hover-label text-sm 4xl:text-lg font-medium max-[1280px]:text-xs">
                                                        <span className="precatorios-table-hover-label-long">
                                                            Acessar detalhes da proposta
                                                        </span>
                                                        <span className="precatorios-table-hover-label-short">
                                                            Ver detalhes
                                                        </span>
                                                    </span>
                                                </Link>
                                            </TableCell>
                                        </TableRow>
                                    ))
                                )}
                            </TableBody>
                        </table>
                    ) : (
                        <table
                            className={cn(
                                'w-full caption-bottom text-sm 4xl:text-lg',
                                isExpanded ? 'min-w-[720px]' : 'min-w-0',
                            )}
                        >
                            <TableHeader>
                                {redeTable.getHeaderGroups().map((headerGroup) => (
                                    <TableRow
                                        key={headerGroup.id}
                                        className="border-transparent hover:bg-transparent"
                                        style={{ borderColor: theme.divider }}
                                    >
                                        {headerGroup.headers.map((header) => (
                                            <TableHead
                                                key={header.id}
                                                className={cn(
                                                    'precatorios-table-head sticky top-0 z-10 text-[10px] 4xl:text-[15px] uppercase tracking-wider shadow-[0_1px_0_0_var(--bento-divider)] max-[1280px]:text-[9px]',
                                                    isExpanded ? 'h-9 px-3' : 'h-7 px-2',
                                                )}
                                                style={{
                                                    background: theme.tableHeaderBg,
                                                    color: theme.textMuted,
                                                }}
                                            >
                                                {flexRender(
                                                    header.column.columnDef.header,
                                                    header.getContext(),
                                                )}
                                            </TableHead>
                                        ))}
                                    </TableRow>
                                ))}
                            </TableHeader>
                            <TableBody>
                                {showNetworkSkeleton ? (
                                    <PrecatoriosTableBodySkeleton
                                        isExpanded={isExpanded}
                                        rowCount={skeletonRowCount}
                                    />
                                ) : redeTable.getRowModel().rows.length === 0 ? (
                                    <TableRow>
                                        <TableCell
                                            colSpan={redeColumns.length}
                                            className="py-8 text-center text-xs 4xl:text-base"
                                            style={{ color: theme.textMuted }}
                                        >
                                            Sua rede ainda não possui propostas cadastradas.
                                        </TableCell>
                                    </TableRow>
                                ) : (
                                    redeTable.getRowModel().rows.map((row) => (
                                        <TableRow
                                            key={row.id}
                                            className="precatorios-table-row border-transparent hover:bg-black/3 dark:hover:bg-white/3"
                                            style={{ borderColor: theme.divider }}
                                        >
                                            {row.getVisibleCells().map((cell) => (
                                                <TableCell
                                                    key={cell.id}
                                                    className={cn(
                                                        'precatorios-table-cell text-xs 4xl:text-base max-[1280px]:text-[11px]',
                                                        isExpanded ? 'px-3 py-2.5' : 'px-2 py-1.5',
                                                    )}
                                                >
                                                    {flexRender(
                                                        cell.column.columnDef.cell,
                                                        cell.getContext(),
                                                    )}
                                                </TableCell>
                                            ))}
                                        </TableRow>
                                    ))
                                )}
                            </TableBody>
                        </table>
                    )}
                </div>

                {activeData && activeData.count > 0 && (
                    <div
                        className="flex shrink-0 items-center justify-between gap-2 border-t px-2 py-1.5 max-[1023px]:px-3 max-[1023px]:py-2"
                        style={{ borderColor: theme.divider }}
                    >
                        <p className="min-w-0 truncate text-[10px] 4xl:text-[15px]" style={{ color: theme.textMuted }}>
                            {paginatedTableDisplayMessage(activePage, activeData)}
                        </p>
                        <div className="flex shrink-0 items-center gap-1">
                            <button
                                type="button"
                                onClick={() =>
                                    activeTab === 'meus'
                                        ? handleChangePage('previous')
                                        : handleChangeNetworkPage('previous')
                                }
                                disabled={!activeData.previous || activeIsFetching}
                                aria-label="Página anterior"
                                className="flex size-6 items-center justify-center rounded-md border text-slate-500 transition-colors hover:text-blue-600 disabled:cursor-not-allowed disabled:opacity-30 max-[1023px]:size-10 dark:text-slate-400 dark:hover:text-blue-300"
                                style={{
                                    borderColor: theme.controlBorder,
                                    background: theme.controlBg,
                                }}
                            >
                                <ChevronLeft className="size-3.5 max-[1023px]:size-4" />
                            </button>
                            <span
                                className="min-w-8 text-center text-[10px] 4xl:text-[15px] font-medium"
                                style={{ color: theme.textMuted }}
                            >
                                {activePage}
                            </span>
                            <button
                                type="button"
                                onClick={() =>
                                    activeTab === 'meus'
                                        ? handleChangePage('next')
                                        : handleChangeNetworkPage('next')
                                }
                                disabled={!activeData.next || activeIsFetching}
                                aria-label="Próxima página"
                                className="flex size-6 items-center justify-center rounded-md border text-slate-500 transition-colors hover:text-blue-600 disabled:cursor-not-allowed disabled:opacity-30 max-[1023px]:size-10 dark:text-slate-400 dark:hover:text-blue-300"
                                style={{
                                    borderColor: theme.controlBorder,
                                    background: theme.controlBg,
                                }}
                            >
                                <ChevronRight className="size-3.5 max-[1023px]:size-4" />
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </TooltipProvider>
    );
}

