} from '@/components/ui/dialog';
import { APP_ROUTES } from '@/constants/app-routes';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { useCanAccessOperationalTriggersScreen } from '@/hooks/use-can-access-operational-triggers';
import { getParticipaRanking, updateParticipaRanking } from '@/services/users';
import { useUserInfoStore } from '@/store/userInfo';
import { useUserPreferencesStore } from '@/store/useUserPreferencesStore';
import { COLORS, TYPOGRAPHY, withAlpha } from '@/design-system';
import {
    Bell,
    Bot,
    Gamepad2,
    LayoutGrid,
    LineChart,
    Monitor,
    PanelLeftOpen,
    Pencil,
    Plus,
    RotateCcw,
    Settings2,
    ShieldCheck,
    TrendingUp,
    Trophy,
    Users,
    Volume2,
    Zap,
} from 'lucide-react';
import Link from 'next/link';
import { useEffect, useId, useState } from 'react';

import {
    ConfiguracoesActionRow,
    ConfiguracoesSection,
    ConfiguracoesThemeRow,
    ConfiguracoesToggleRow,
} from './_components/configuracoes-ui';
import { NotificationPreferencesPanel } from './_components/NotificationPreferencesPanel';
import { TwoFactorCard } from './_components/TwoFactorCard';
import { getConfiguracoesCanvasStyle, getConfiguracoesPanelStyle } from './_lib/configuracoes-shared';
import { canAccessGruposCompartilhamento } from './grupos-compartilhamento/_lib/grupos-compartilhamento-access';
import { ScenariosModalType, ScenariosProjectionModalProps } from './types';

export default function ConfiguracoesPage() {
    const {
        preferences,
        setShowMessageNotifications,
        setShowGamification,
        setParticipaRanking,
        setPlaySounds,
        setExpandSidebarSections,
        resetToDefaults,
        resetBrokerDashboardLayout,
    } = useUserPreferencesStore();

    const userInfo = useUserInfoStore((s) => s.data);
    const canViewScenarios = userInfo?.role === 'MASTER' || userInfo?.role === 'DEV';
    const canViewAiStudio = userInfo?.role === 'MASTER';
    const canManageBrokerDashboardLayout = userInfo?.role === 'COMERCIAL_BROKER';
    const canManageOperationalTriggersPage = useCanAccessOperationalTriggersScreen({
        host: userInfo?.host,
        role: userInfo?.role,
        isSuperuser: userInfo?.is_superuser,
    });
    const canManageSharingGroups = canAccessGruposCompartilhamento({
        role: userInfo?.role,
        isSuperuser: userInfo?.is_superuser,
    });

    const [modalStates, setModalStates] = useState<ScenariosProjectionModalProps>({
        isOpen: false,
        modalType: null,
    });
    const [indexRulesCreateOpen, setIndexRulesCreateOpen] = useState(false);
    const [indexRulesListOpen, setIndexRulesListOpen] = useState(false);
    const [resetDialogOpen, setResetDialogOpen] = useState(false);
    const [resetBrokerLayoutDialogOpen, setResetBrokerLayoutDialogOpen] = useState(false);

    const messageNotificationsId = useId();
    const gamificationId = useId();
    const rankingId = useId();
    const soundsId = useId();
    const sidebarId = useId();
    const themeId = useId();

    function handleOpenModal(type: ScenariosModalType) {
        setModalStates({ isOpen: true, modalType: type });
    }

    function handleCloseModal() {
        setModalStates({ isOpen: false, modalType: null });
    }

    useEffect(() => {
        let mounted = true;
        (async () => {
            const data = await getParticipaRanking();
            if (!mounted) return;
            if (typeof data?.participa_ranking === 'boolean') {
                setParticipaRanking(data.participa_ranking);
            }
        })();
        return () => {
            mounted = false;
        };
    }, [setParticipaRanking]);

    const handleParticipaRankingChange = async (checked: boolean) => {
        const previous = preferences.notifications.participaRanking;
        setParticipaRanking(checked);
        const toastId = sendToastMessage({ title: 'Salvando preferência...', type: 'loading' });
        try {
            await updateParticipaRanking(checked);
            sendToastMessage({
                title: 'Preferência atualizada com sucesso.',
                type: 'success',
                previousToastId: toastId,
            });
        } catch {
            setParticipaRanking(previous);
            sendToastMessage({
                title: 'Não foi possível atualizar a preferência.',
                type: 'error',
                previousToastId: toastId,
            });
        }
    };

    function handleConfirmReset() {
        resetToDefaults();
        setResetDialogOpen(false);
        sendToastMessage({ title: 'Preferências restauradas ao padrão.', type: 'success' });
    }

    function handleConfirmBrokerLayoutReset() {
        resetBrokerDashboardLayout();

