'use client';
import { parseAsBoolean, parseAsString, useQueryState, useQueryStates } from 'nuqs';
import { BrokerInfoHeader } from './BrokerInfoHeader';
import { BrokerInfoValueCards } from './BrokerInfoValueCards';
import { BrokerInfoTable } from './Table/BrokerInfoTable';

import { useIsMobile } from '@/hooks/use-mobile';
import { Suspense, useRef, useState } from 'react';
import { BrokerProposalList } from './Card/List';
import { ProposalListWrapper } from './ProposalListWrapper';
import { BrokerInfoValueCardsSkeleton } from './Skeletons';
import { BrokerNetworkValueCards } from './BrokerNetworkValueCards';
import { NetworkProposalListWrapper } from './NetworkProposalListWrapper';

export default function BrokerInfo() {


    // ================
    // # Nuqs
    // ================
    const [urlFilters, setUrlFilters] = useQueryStates({
        credor: parseAsString,
        valor_liquido: parseAsString,
        proposta_escolhida: parseAsString,
        comissao_escolhida: parseAsString,
        status: parseAsString,
        exigencias: parseAsBoolean,
        criado_por: parseAsString,
        esfera: parseAsString,
        tribunal: parseAsString,
        coordenador: parseAsString,
        host: parseAsString,
    });

    const isMobile = useIsMobile();
    const [activeTab, setActiveTab] = useQueryState('tab', {
        defaultValue: 'meus',
        parse: (value) => (value === 'rede' ? 'rede' : 'meus'),
        serialize: (value) => value,
    });

    const tabsRef = useRef<HTMLDivElement>(null);

    function goToRedeTab() {
        setActiveTab('rede');
        setTimeout(() => {
            tabsRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }, 50);
    }

    return (
        <section className="col-span-12 grid grid-cols-12 gap-6">
            <BrokerInfoHeader setActiveTab={goToRedeTab} />

            <div ref={tabsRef} className="col-span-12 border-b border-border flex gap-6 px-4">
                <button
                    onClick={() => setActiveTab('meus')}
                    className={`pb-3 font-medium text-sm transition-colors border-b-2 ${activeTab === 'meus'
                        ? 'border-app-default text-app-default'
                        : 'border-transparent text-paragraph hover:text-subtitle'
                        }`}
                >
                    Meus Precatórios
                </button>
                <button
                    onClick={() => setActiveTab('rede')}
                    className={`pb-3 font-medium text-sm transition-colors border-b-2 ${activeTab === 'rede'
                        ? 'border-app-default text-app-default'
                        : 'border-transparent text-paragraph hover:text-subtitle'
                        }`}
                >
                    Rede de Brokers
                </button>
            </div>

            {activeTab === 'meus' ? (
                <>
                    <Suspense fallback={<BrokerInfoValueCardsSkeleton />}>
                        <BrokerInfoValueCards urlFilters={urlFilters} setUrlFilters={setUrlFilters} />
                    </Suspense>
                    {isMobile !== undefined ? (
                        <ProposalListWrapper
                            urlFilters={urlFilters}
                            setUrlFilters={setUrlFilters}
                            isMobile={isMobile}
                        >
                            {isMobile ? <BrokerProposalList /> : <BrokerInfoTable />}
                        </ProposalListWrapper>
                    ) : null}
                </>
            ) : (
                <>
                    <BrokerNetworkValueCards />
                    <div className="col-span-12">
                        <NetworkProposalListWrapper />
                    </div>
                </>
            )}
        </section>
    );

