/** Fechamento pelo X, Escape ou "Voltar" — todos passam por aqui para checar rascunho não salvo. */
const requestCloseOficioDialog = () => {
    if (isOficioFormDirty) {
        setIsCloseOficioConfirmOpen(true);
        return;
    }
    closeOficioDialog();
};

const openOficioDialog = (oficio: IDropzoneDocReturn | null) => {
    setExtractedOficio(oficio);
    setOficioDialogSessionKey((key) => key + 1);
    setIsOficioDialogOpen(true);
};

const usedWidgetIds = Object.values(slotWidgets).filter(
    (id): id is NonNullable<typeof id> => id !== null,
);

useEffect(() => {
    if (!openEmptySlotId) return;

    function handleClickOutside(event: MouseEvent) {
        const target = event.target as Element;
        if (target.closest(`[data-bento-card-id="${openEmptySlotId}"]`)) return;
        setOpenEmptySlotId(null);
    }

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
}, [openEmptySlotId]);

useEffect(() => {
    if (draggingWidgetId) setOpenEmptySlotId(null);
}, [draggingWidgetId]);

useGSAP(
    () => {
        const prefersReducedMotion = window.matchMedia(
            '(prefers-reduced-motion: reduce)',
        ).matches;
        if (prefersReducedMotion) return;
        gsap.fromTo(
            '[data-bento-card-id]',
            { y: 20, opacity: 0 },
            {
                y: 0,
                opacity: 1,
                stagger: 0.06,
                duration: 0.5,
                ease: 'power3.out',
                clearProps: 'opacity,transform',
            },
        );
    },
    { scope: mountRef },
);

// Unifica os dois tipos de arraste — reposicionar um slot (grip) e soltar um
// widget da lista — para que ambos tenham o mesmo feedback: ghost no cursor e
// overlay "Trocar por X" no card alvo. Os dois nunca ocorrem ao mesmo tempo.
const activeDragWidgetId =
    draggingWidgetId ?? pendingWidgetId ?? (draggingId ? slotWidgets[draggingId] : null);
const activeDropTargetId = widgetDropTargetId ?? dropTargetId;
const incomingWidgetLabel = activeDragWidgetId
    ? WIDGET_REGISTRY[activeDragWidgetId].label
    : undefined;
const isPendingPlacement = pendingWidgetId !== null;

function cardProps(id: BentoCardId) {
    const style = getGridStyle(id);
    const isDimmed = expandedCardId !== null && id !== expandedCardId;
    // Slot ocupado por um widget fixo: não pode ser removido nem receber outro
    // widget (da reserva ou pendente). A troca entre cards continua permitida.
    const isFixedSlot = isFixedWidget(slotWidgets[id]);
    const rejectsIncomingWidget = isFixedSlot && widgetDropTargetId === id;

    return {
        id,
        gridColumn: style.gridColumn,
        gridRow: style.gridRow,
        isDragging: draggingId === id,
        isDimmed,
        isInteractionDisabled,
        hideDragHandle: isMobileOrTablet,
        isWidgetDropTarget: activeDropTargetId === id && !rejectsIncomingWidget,
        isPendingPlaceTarget: isPendingPlacement && !isFixedSlot,
        incomingWidgetLabel,
        onPendingPlace:
            pendingWidgetId && !isFixedSlot
                ? () => placeWidgetOnSlot(id, pendingWidgetId)
                : undefined,
        onRemoveWidget:
            slotWidgets[id] != null && !isInteractionDisabled && !isFixedSlot
                ? () => {
                      clearSlotWidget(id);
                      setOpenEmptySlotId((current) => (current === id ? null : current));
                  }
                : undefined,

