'use client';

import { ContentHeader } from '@/components/Header/ContentHeader';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { AuditServices } from '@/services/audit';
import { useUserInfoStore } from '@/store/userInfo';
import { ScenariosTableSkeleton } from '@/components/Skeletons/ScenariosTableSkeleton';
import { CalculatorIcon, Calendar, Info, Plus } from 'lucide-react';
import { Suspense, useState } from 'react';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { HistoricResultsModal } from './_components/HistoricResultsModal';
import { MonitoryInfoModal } from './_components/MonitoryInfoModal';
import { ScenariosTable } from './_components/ScenariosTable';
import { useQuery } from '@tanstack/react-query';
import { useGetStaffUsersQueryOptions } from '@/hooks/queries/users';
import { Scenario } from '@/types/scenario';
import { AuditCalculatorPayload } from './types';

export default function MonitoramentoCalculadora() {
    const { data: userData } = useUserInfoStore();

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedScenario, setSelectedScenario] = useState<Scenario | null>(null);
    const [isResultsModalOpen, setIsResultsModalOpen] = useState(false);

    const [inputPayload, setInputPayload] = useState<AuditCalculatorPayload | null>(null);
    const [notifiedUsers, setNotifiedUsers] = useState<string[]>([]);
    const [selectedIds, setSelectedIds] = useState<string[]>([]);

    const { data: superUsers } = useQuery(
        useGetStaffUsersQueryOptions({ isEnabled: userData?.is_staff }),
    );

    const handleBulkAction = async (action: 'delete' | 'activate' | 'deactivate') => {
        if (selectedIds.length === 0) return;

        const confirmMsg =
            action === 'delete'
                ? `Tem certeza que deseja excluir ${selectedIds.length} cenários?`
                : `Deseja ${action === 'activate' ? 'ativar' : 'desativar'} ${selectedIds.length} cenários?`;

        if (!confirm(confirmMsg)) return;

        try {
            await AuditServices.bulkAction(selectedIds, action);
            sendToastMessage({ type: 'success', title: 'Ação realizada com sucesso' });
            setSelectedIds([]);
        } catch {
            sendToastMessage({ type: 'error', title: 'Erro ao realizar ação em lote' });
        }
    };

    const handleViewResults = async (scenario: Scenario) => {
        setSelectedScenario(scenario);
        setIsResultsModalOpen(true);
    };

    const openModal = (scenario: Scenario | null = null) => {
        setSelectedScenario(scenario);
        if (scenario) {
            setInputPayload(scenario.input_payload);
            setNotifiedUsers((scenario.notified_users || []).map((id) => id.toString()));
        } else {
            setInputPayload(null);

            // Selecionar usuário logado por padrão se for novo cenário
            if (userData?.user) {
                const currentUser = superUsers?.find((u) => u.username === userData.user);
                if (currentUser) {
                    setNotifiedUsers([currentUser.id.toString()]);
                } else {
                    setNotifiedUsers([]);
                }
            } else {
                setNotifiedUsers([]);
            }
        }
        // setFormErrors({});
        setIsModalOpen(true);
    };

    if (!userData?.is_staff) {
        return (
            <Alert variant="destructive">
                <Info className="h-4 w-4" />
                <AlertDescription>Acesso restrito a administradores.</AlertDescription>
            </Alert>
        );
    }

    return (
        <div className="space-y-6">
            <div className="mb-6 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                <ContentHeader
                    title="Monitoramento da Calculadora"
                    subtitle="Auditoria automática e integridade de cálculos"
                    icon={CalculatorIcon}
                />

