'use client';

import BrokerInfo from '@/app/crm/broker/_components/BrokerInfo/index';
import { OficioDropzone } from '@/app/crm/broker/_components/OficioDropzone';
import { OficioForm } from '@/app/crm/broker/_components/OficioForm';
import { Button } from '@/components/ui/button';
import { IDropzoneDocReturn } from '@/interfaces/IDropzoneDocReturn';
import { cn } from '@/lib/utils';
import { ArrowDown } from 'lucide-react';
import { useRef, useState } from 'react';
import posthog from 'posthog-js';

/**
 * Componente para cadastro de novos brokers
 */
function Broker() {
    const [currentStep, setCurrentStep] = useState(0);
    const [oficio, setOficio] = useState<IDropzoneDocReturn | null>(null);
    const bottomSectionRef = useRef<HTMLDivElement>(null);

    const handleNext = () => {
        if (currentStep < 1) {
            setCurrentStep((prev) => prev + 1);
            if (currentStep === 0 && !oficio) {
                posthog.capture('crm_broker_manual_fill_clicked');
            }
        }
    };

    const handlePrevious = () => {
        if (currentStep > 0) {
            setCurrentStep((prev) => prev - 1);
        }
    };

    const scrollToBottom = () => {
        posthog.capture('crm_broker_scroll_to_proposals_clicked');
        bottomSectionRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    };

    // Calcula a altura: 100vh - altura do header (assumindo ~80px)
    const containerHeight = 'calc(100vh - 144px)';

    return (
        <div className="relative flex flex-col gap-10">
            {/* Primeira seção - Multi-step com animação */}
            <div
                id="broker-top"
                className="relative w-full overflow-hidden rounded-lg bg-boxdark"
                style={{ height: containerHeight }}
            >
                <div
                    className={cn(
                        'flex h-full w-[200%] transition-transform duration-300 ease-in-out',
                        currentStep === 0 ? 'translate-x-0' : '-translate-x-1/2',
                    )}
                >
                    {/* Step 0 - Tela inicial com instruções */}
                    <div
                        className={cn(
                            'h-full w-1/2 shrink-0 overflow-y-auto overflow-x-hidden transition-opacity duration-300',
                            currentStep === 0 ? 'opacity-100' : 'pointer-events-none opacity-0',
                        )}
                    >
                        <div className="flex h-full w-full flex-col items-center justify-between p-3 3xl:p-8">
                            <div className="flex flex-col w-full gap-4 items-center 3xl:gap-6">
                                <OficioDropzone setOficio={setOficio} handleNext={handleNext} />
                                <div className="flex w-full max-w-2xl xl:max-w-3xl 3xl:max-w-5xl items-center justify-center gap-4 px-4">
                                    <div className="h-0.5 flex-1 bg-boxdark-2" />
                                    <p className="shrink-0 text-sm text-subtitle">OU</p>
                                    <div className="h-0.5 flex-1 bg-boxdark-2" />
                                </div>

                                <Button
                                    onClick={handleNext}
                                    className="h-fit w-fit whitespace-break-spaces text-sm 3xl:text-lg 2xsm:p-4"
                                >
                                    Clique aqui para preencher manualmente
                                </Button>
                            </div>

                            <Button
                                variant="ghost"
                                className="gap-2 whitespace-break-spaces 2xsm:h-fit sm:h-10 "
                                onClick={scrollToBottom}
                            >
                                <ArrowDown className="h-5 w-5 animate-jump" />
                                <span className="text-sm font-medium">
                                    Arraste abaixo para visualizar propostas já cadastradas
                                </span>
                            </Button>
                        </div>
                    </div>

                    {/* Step 1 - Formulário */}
                    <div
                        className={cn(
                            'h-full w-1/2 shrink-0 overflow-y-auto transition-opacity duration-300',
                            currentStep === 1 ? 'opacity-100' : 'pointer-events-none opacity-0',
                        )}
                    >
                        <OficioForm oficio={oficio} handlePrevious={handlePrevious} />
                    </div>
                </div>
            </div>

            {/* Segunda seção - Lista de precatórios cadastrados */}
            <div
                ref={bottomSectionRef}
                className={cn('min-h-screen', currentStep !== 0 && 'hidden')}
            >
                <BrokerInfo />
            </div>
        </div>
    );
}

export default Broker;

